Theorem dispatch_correct:forall fuel name args,
 dispatch fuel name args=call_reference nilof extra cpc_operators fuel typeof cpc_programs name args.
Proof.
 intro fuel;induction fuel using lt_wf_ind;intros name args.
 unfold dispatch,compiled,call_reference;cbn [named cpc_programs].
destruct(String.eqb name "$aci_norm_eq") eqn:Hname0;[rewrite helper_0_body;apply EoDirect.run_program_correct;intros;apply H;assumption|].
destruct(String.eqb name "$arith_mk_one") eqn:Hname1;[rewrite helper_1_body;apply EoDirect.run_program_correct;intros;apply H;assumption|].
